        sse_encode_i_32(2, serializer);
        sse_encode_box_autoadd_bridge_resource_stamp(stamp, serializer);
        sse_encode_String(accountId, serializer);
        sse_encode_opt_box_autoadd_bridge_model_catalog_account_dto(
          catalog,
